function getSplunkSecurityTranslation(key, lang) {
    return (splunksecurityTranslations[lang] && splunksecurityTranslations[lang][key]) ||
           (splunksecurityTranslations.en && splunksecurityTranslations.en[key]) || null;
}

function applySplunkSecurityTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.splunk-security.") || key.startsWith("review.common."))) {
            const translation = getSplunkSecurityTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} splunk-security translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applySplunkSecurityTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applySplunkSecurityTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applySplunkSecurityTranslations(window.i18n?.getCurrentLanguage() || "en");
}
